examples.template:
MonarchSectionCard(
    {{messages.title}},
    description: {{messages.description}},
    systemImage: "cpu"
) {
    VStack(alignment: .leading, spacing: 16) {
        Text({{messages.appsTitle}})
            .monarchTextStyle(.label)
        Text({{messages.appsDescription}})
            .monarchTextStyle(.caption)
        VStack(alignment: .leading) {
            Toggle({{apps.0.label}}, isOn: binding(for: {{apps.0.id}}))
            Text({{apps.0.description}})
                .monarchTextStyle(.caption)
        }
        VStack(alignment: .leading) {
            Toggle({{apps.1.label}}, isOn: binding(for: {{apps.1.id}}))
            Text({{apps.1.description}})
                .monarchTextStyle(.caption)
        }
        Toggle({{apps.2.label}}, isOn: binding(for: {{apps.2.id}}))
        VStack(alignment: .leading) {
            Toggle({{messages.dataSharing}}, isOn: $sharing)
            Text({{messages.dataSharingDescription}})
                .monarchTextStyle(.caption)
        }
        VStack(alignment: .leading) {
            Toggle({{messages.memory}}, isOn: $memory)
            Text({{messages.memoryDescription}})
                .monarchTextStyle(.caption)
        }
        MonarchSelectField(
            {{messages.retention}},
            selection: $retention,
            options: [
                MonarchSelectOption({{retentionOptions.0.label}}, value: {{retentionOptions.0.value}}),
                MonarchSelectOption({{retentionOptions.1.label}}, value: {{retentionOptions.1.value}}),
                MonarchSelectOption({{retentionOptions.2.label}}, value: {{retentionOptions.2.value}}),
                MonarchSelectOption({{retentionOptions.3.label}}, value: {{retentionOptions.3.value}}),
            ],
            helper: {{messages.retentionDescription}}
        )
        MonarchSelectField(
            {{messages.provider}},
            selection: $provider,
            options: [
                MonarchSelectOption({{messages.providerDefault}}, value: {{value.provider}}),
                MonarchSelectOption({{providers.0.label}}, value: {{providers.0.id}}),
                MonarchSelectOption({{providers.1.label}}, value: {{providers.1.id}}),
            ],
            helper: {{messages.providerDescription}}
        )
    }
} footer: {
    HStack {
        Spacer()
        MonarchButton({{messages.discard}}) {
            apps = savedApps
            sharing = savedSharing
            memory = savedMemory
            retention = savedRetention
            provider = savedProvider
        }
        .disabled(!isDirty)
        MonarchButton({{messages.save}}, variant: .primary) {
            // The app saves the draft here.
            savedApps = apps
            savedSharing = sharing
            savedMemory = memory
            savedRetention = retention
            savedProvider = provider
        }
        .disabled(!isDirty)
    }
}

examples.setupTemplate:
@State private var apps: [String: Bool] = [
    {{apps.0.id}}: {{value.apps.docs}},
    {{apps.1.id}}: {{value.apps.mail}},
    {{apps.2.id}}: {{value.apps.calendar}},
]
@State private var savedApps: [String: Bool] = [
    {{apps.0.id}}: {{value.apps.docs}},
    {{apps.1.id}}: {{value.apps.mail}},
    {{apps.2.id}}: {{value.apps.calendar}},
]
@State private var sharing = {{value.dataSharing}}
@State private var savedSharing = {{value.dataSharing}}
@State private var memory = {{value.memory}}
@State private var savedMemory = {{value.memory}}
@State private var retention = {{value.retention}}
@State private var savedRetention = {{value.retention}}
@State private var provider = {{value.provider}}
@State private var savedProvider = {{value.provider}}

private var isDirty: Bool {
    apps != savedApps || sharing != savedSharing || memory != savedMemory
        || retention != savedRetention || provider != savedProvider
}

private func binding(for app: String) -> Binding<Bool> {
    Binding(
        get: { apps[app] ?? false },
        set: { apps[app] = $0 }
    )
}

